/**
 * Unit tests for CategoryPlot.removeRangeMarker.
 */
public class CategoryPlot_removeRangeMarker_TriageGen0Test {

    private CategoryPlot plot;
    private Marker mockMarker;
    private CategoryDataset mockDataset;
    private CategoryAxis mockDomainAxis;
    private ValueAxis mockRangeAxis;

    @Before
    public void setUp() {
        mockDataset = Mockito.mock(CategoryDataset.class);
        mockDomainAxis = Mockito.mock(CategoryAxis.class);
        mockRangeAxis = Mockito.mock(ValueAxis.class);
        mockMarker = Mockito.mock(Marker.class);

        plot = new CategoryPlot(mockDataset, mockDomainAxis, mockRangeAxis, null);
    }

    /**
     * Tests that passing a null marker throws IllegalArgumentException.
     */
    @Test(expected = IllegalArgumentException.class)
    public void testRemoveRangeMarker_NullMarker_ThrowsException() {
        plot.removeRangeMarker(0, null, Layer.FOREGROUND, true);
    }

    /**
     * Tests successful removal from the FOREGROUND layer.
     */
    @Test
    public void testRemoveRangeMarker_ForegroundSuccess() {
        int index = 0;
        // We need to inject a marker into the internal list. 
        // Since the internal maps are not exposed via setters, 
        // we assume addRangeMarker exists or we simulate the state.
        // In JFreeChart, addRangeMarker is the standard way to populate these.
        plot.addRangeMarker(index, mockMarker, Layer.FOREGROUND);

        boolean result = plot.removeRangeMarker(index, mockMarker, Layer.FOREGROUND, true);
        assertTrue("Marker should have been removed", result);
    }

    /**
     * Tests successful removal from the BACKGROUND layer.
     */
    @Test
    public void testRemoveRangeMarker_BackgroundSuccess() {
        int index = 0;
        plot.addRangeMarker(index, mockMarker, Layer.BACKGROUND);

        boolean result = plot.removeRangeMarker(index, mockMarker, Layer.BACKGROUND, true);
        assertTrue("Marker should have been removed", result);
    }

    /**
     * Tests removal when the marker is not in the list.
     */
    @Test
    public void testRemoveRangeMarker_MarkerNotFound() {
        int index = 0;
        Marker differentMarker = Mockito.mock(Marker.class);
        plot.addRangeMarker(index, mockMarker, Layer.FOREGROUND);

        boolean result = plot.removeRangeMarker(index, differentMarker, Layer.FOREGROUND, true);
        assertFalse("Should return false when marker is not present", result);
    }

    /**
     * Tests the 'notify' flag behavior. 
     * Note: We cannot easily verify fireChangeEvent() without a listener, 
     * but we cover the branch logic.
     */
    @Test
    public void testRemoveRangeMarker_NotifyFalse() {
        int index = 0;
        plot.addRangeMarker(index, mockMarker, Layer.FOREGROUND);

        // If notify is false, it should still return true but not fire event
        boolean result = plot.removeRangeMarker(index, mockMarker, Layer.FOREGROUND, false);
        assertTrue(result);
    }

    /**
     * Tests the edge case where the index might be out of bounds 
     * (handled by the underlying Map/ArrayList).
     */
    @Test(expected = NullPointerException.class)
    public void testRemoveRangeMarker_InvalidIndex_ThrowsException() {
        // Accessing a non-existent index in the internal Map will return null,
        // causing a NullPointerException when calling .remove() on the markers list.
        plot.removeRangeMarker(999, mockMarker, Layer.FOREGROUND, true);
    }
}

/**
 * Mock/Stub for Marker if not available in the scope, 
 * though usually provided by JFreeChart.
 */
interface Marker {}
